const AXES=[{"en": "Attention control", "ar": "التحكم بالانتباه", "scope": "corpus", "questions": [["Is attention disproportionately concentrated on one issue?", "هل يتم توجيه التركيز العام نحو قضية واحدة بشكل مبالغ فيه؟"], ["Are parallel issues being marginalized or ignored?", "هل توجد ملفات موازية يتم تهميشها أو تجاهلها؟"], ["Has coverage of a previously prominent issue suddenly stopped?", "هل حدث صمت مفاجئ حول موضوع كان حاضرًا سابقًا؟"], ["What has disappeared from the observed coverage?", "ما الذي اختفى من المشهد فجأة؟"], ["Is there evidence that this focus conceals another activity?", "هل يخدم هذا التركيز عملية إخفاء نشاط آخر؟"]]}, {"en": "Information flooding", "ar": "الإغراق المعلوماتي", "scope": "corpus", "questions": [["Are many reports appearing without substantive developments?", "هل يتم ضخ عدد كبير من الأخبار دون تطور نوعي حقيقي؟"], ["Are reports similar in wording and content?", "هل الأخبار متشابهة في الصياغة والمضمون؟"], ["Are terms repeated without new information?", "هل تتكرر المصطلحات ذاتها دون إضافة معلومات جديدة؟"], ["Is there actual progress or recycled content?", "هل هناك تقدم فعلي أم مجرد إعادة تدوير للمحتوى؟"], ["Does volume obscure a lack of strong evidence?", "هل الكم يغطي على غياب الدليل القوي؟"]]}, {"en": "Source traceability", "ar": "المصدر المجهول / غير القابل للتحقق", "scope": "text", "questions": [["Does the account rely on unnamed informed sources?", "هل تعتمد الرواية على مصادر مطلعة غير محددة؟"], ["Does it invoke vague close circles or third parties?", "هل يتم الاستناد إلى دوائر قريبة أو أطراف ثالثة غامضة؟"], ["Can the source be questioned or independently checked?", "هل يمكن مساءلة المصدر أو التحقق منه؟"], ["Who may benefit from ambiguity, and what evidence connects them?", "من المستفيد من الغموض؟"], ["Is authority asserted without a means of examination?", "هل يتم خلق سلطة معرفية دون قابلية للفحص؟"]]}, {"en": "Timing & decision pressure", "ar": "التوقيت مع ضغط القرار", "scope": "context", "questions": [["Did publication precede an important political or military decision?", "هل جاء التسريب أو الخبر قبيل قرار سياسي أو عسكري مهم؟"], ["Did the story emerge at the peak of a crisis?", "هل ظهر الخبر عند ذروة توتر أو أزمة؟"], ["What explains publication at this particular time?", "لماذا الآن تحديدًا؟"], ["Does the timing put pressure on decision makers?", "هل يضغط التوقيت على متخذ القرار؟"], ["Can analysis time be separated from the decision deadline?", "هل يمكن فصل زمن التحليل عن زمن القرار؟"]]}, {"en": "Narrative coherence", "ar": "التماسك السردي المفرط", "scope": "text", "questions": [["Does the story appear unusually complete despite limited evidence?", "هل الرواية مكتملة بشكل مريح أكثر من اللازم؟"], ["Are normal gaps and uncertainties omitted?", "هل تغيب الفجوات أو مناطق الغموض الطبيعية؟"], ["Does it give ready-made answers to every potential question?", "هل تقدم إجابات جاهزة لكل سؤال محتمل؟"], ["Where are the inconsistencies or unresolved tensions?", "أين التناقض الطبيعي في الرواية؟"], ["Does the presentation discourage critical questioning?", "هل هذا التماسك يخدم منع التساؤل النقدي؟"]]}, {"en": "Threat framing", "ar": "تضخيم أو تقليل التهديد", "scope": "context", "questions": [["Is threatening language disproportionate to verified actions?", "هل الخطاب التهديدي مفرط مقارنة بالفعل؟"], ["Are observed actions more symbolic than operational?", "هل توجد تحركات رمزية أكثر من كونها عملياتية؟"], ["Do verified actions match the rhetoric?", "هل الفعل يوازي الخطاب؟"], ["Is there evidence of an attempt to provoke an unbalanced response?", "هل الهدف دفع الخصم لرد فعل غير متوازن؟"], ["How do documented costs compare with the rhetoric?", "ما الكلفة الحقيقية مقارنة بحجم التهويل؟"]]}, {"en": "Cross-domain coordination", "ar": "التنسيق المفرط عبر المجالات", "scope": "corpus", "questions": [["Is there notable timing alignment across media, military and politics?", "هل هناك تزامن لافت بين الإعلام والعسكر والسياسة؟"], ["Does presentation appear more coordinated than the usual baseline?", "هل يظهر المشهد بإخراج متقن أكثر من المعتاد؟"], ["Is this level of alignment typical of the actors involved?", "هل يعكس الواقع عادة هذا القدر من الانضباط؟"], ["What evidence distinguishes coordination from a shared cause?", "هل يمكن أن يكون التنسيق مصطنعًا لإيصال رسالة محددة؟"], ["How does this compare with ordinary event variability?", "هل الواقع يُخرج عادة بهذا الإتقان؟"]]}, {"en": "Response proportionality", "ar": "رد الفعل المبالغ فيه", "scope": "context", "questions": [["Was the response unusually rapid and escalatory?", "هل جاء الرد سريعًا وبشكل تصعيدي غير متدرج؟"], ["Are actions disproportionate to the documented event?", "هل توجد تحركات لا تتناسب مع الحدث؟"], ["Does the response depart from previous behavior?", "هل يمثل الرد انحرافًا عن السلوك الطبيعي السابق؟"], ["What distinguishes a normal response from possible inducement?", "هل هذا رد فعل أم استدراج ناجح؟"], ["Is there evidence connecting the response to a deception attempt?", "هل يمكن اعتبار الاستجابة مؤشر نجاح عملية خداع؟"]]}, {"en": "Analytical openness", "ar": "الإغلاق المعرفي", "scope": "team", "questions": [["Did the analytical team reach unusually rapid consensus?", "هل حدث إجماع سريع داخل المؤسسة التحليلية؟"], ["Were criticism or alternative hypotheses rejected?", "هل يتم رفض النقد أو الفرضيات البديلة؟"], ["Was the deception hypothesis seriously tested?", "هل تم اختبار فرضية الخداع بشكل جدي؟"], ["Did we consider that our own interpretation could be wrong?", "هل افترضنا أننا قد نكون مخدوعين؟"], ["Was discussion closed before analysis was complete?", "هل أُغلق النقاش قبل استكمال التحليل؟"]]}];
'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
let state={version:1,cases:[],settings:{lang:'ar',model:'gpt-5.6-terra',reportLanguage:'Arabic',org:'غرفة أخبار مستقلة'}},bridge=false,token='',current=null,tab='sources',busy=false;
const statuses=['unassessed','supported','mixed','not_observed','insufficient','not_applicable'];
const T=(en,ar)=>state.settings.lang==='ar'?ar:en;
const statusName=s=>({unassessed:T('Not reviewed','لم يُراجع'),supported:T('Indicator supported','مؤشر مدعوم'),mixed:T('Mixed evidence','أدلة مختلطة'),not_observed:T('Not observed in scope','لم يُرصد ضمن النطاق'),insufficient:T('Insufficient information','معلومات غير كافية'),not_applicable:T('Not applicable','لا ينطبق')}[s]||s);
const scopes={text:['Text & evidence','النص والأدلة'],corpus:['Multiple sources over time','مصادر متعددة عبر الزمن'],context:['External context required','يحتاج سياقًا خارجيًا'],team:['Human team review','مراجعة بشرية للفريق']};
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',files:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',method:'<path d="m9 6 2 2 4-4M9 14l2 2 4-4M4 5v15h16V5"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',integrations:'<path d="M8 12h8M12 8v8"/><circle cx="12" cy="12" r="9"/>',claims:'<path d="M4 4h16v16H4zM8 9h8M8 13h6M8 17h4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${icons[n]||icons.files}</svg>`;
const fmt=s=>{try{return new Date(s).toLocaleString(state.settings.lang==='ar'?'ar-LB':'en-GB',{dateStyle:'medium',timeStyle:'short'})}catch{return s}};
const safeURL=u=>{try{let v=new URL(u);return ['https:','http:'].includes(v.protocol)?v.href:''}catch{return ''}};
const link=(u,label)=>safeURL(u)?`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer">${esc(label||u)}</a>`:esc(label||u||'');
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,data){if(!bridge)throw Error(T('This feature is available in the full desktop version.','هذه الميزة متاحة في نسخة الكمبيوتر الكاملة.'));let r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Raqeeb-Token':token},body:data===undefined?undefined:JSON.stringify(data)});let out=await r.json();if(!r.ok)throw Error(out.error||'Request failed');return out}
let saveQueue=Promise.resolve();
function persist(){const snapshot=JSON.stringify(state);try{localStorage.setItem('raqeeb-v1',snapshot)}catch{notify(T('Browser storage unavailable. Export a backup.','تعذّر الحفظ في المتصفح. صدّر نسخة احتياطية.'))}if(bridge)saveQueue=saveQueue.catch(()=>{}).then(()=>api('state',JSON.parse(snapshot))).catch(e=>notify(e.message));}
function shell(){document.body.dir=state.settings.lang==='ar'?'rtl':'ltr';document.documentElement.lang=state.settings.lang;document.documentElement.dir=document.body.dir;document.querySelectorAll('[data-en]').forEach(el=>el.textContent=T(el.dataset.en,el.dataset.ar));$('#lang').textContent=T('العربية','English');$('#connection').textContent=bridge?T('SECURE API BRIDGE','جسر API آمن'):T('LOCAL-FIRST WORKSPACE','مساحة محلية أولًا');let route=location.hash.slice(1).split('/')[0]||'home';$('#nav').innerHTML=[['home','Verification desk','مكتب التحقق'],['files','Case files','ملفات القضايا'],['integrations','Integrations','التكاملات'],['method','Methodology','المنهجية'],['settings','Settings & backup','الإعدادات والنسخ']].map(([id,en,ar])=>`<a href="#${id}" class="${route===id||(route==='case'&&id==='files')?'active':''}">${icon(id)}${T(en,ar)}</a>`).join('');$('#breadcrumb').textContent=T('Workspace / ','مساحة العمل / ')+({home:T('Verification desk','مكتب التحقق'),files:T('Case files','ملفات القضايا'),case:T('Case analysis','تحليل القضية'),integrations:T('Integrations','التكاملات'),method:T('Methodology','المنهجية'),settings:T('Settings','الإعدادات')}[route]||'');}
function bind(id,event,fn){let x=$(id);if(x)x.addEventListener(event,fn)}
function render(){shell();let [route,id]=(location.hash.slice(1)||'home').split('/');current=state.cases.find(c=>c.id===id)||null;if(route==='case'&&current)renderCase();else if(route==='files')renderFiles();else if(route==='integrations')renderIntegrations();else if(route==='method')renderMethod();else if(route==='settings')renderSettings();else renderHome();}
function caseCard(c){return `<article class="card case-card" tabindex="0" role="link" data-case="${esc(c.id)}"><div class="row"><span class="badge ${c.sample?'amber':''}">${c.sample?T('FICTIONAL SAMPLE','مثال خيالي'):T('WORKING FILE','ملف عمل')}</span><span class="small muted">${c.sources.length} ${T('sources','مصادر')}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.question||T('Article verification & structured review','تحقق من المقال ومراجعة منظمة'))}</p><div class="card-foot"><span>${fmt(c.created)}</span><span>${T('Open file','فتح الملف')} ↗</span></div></article>`}
function bindCards(){document.querySelectorAll('[data-case]').forEach(el=>{let open=()=>{tab='sources';location.hash='case/'+el.dataset.case};el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter')open()}})}
function renderHome(){let sources=state.cases.reduce((n,c)=>n+c.sources.length,0),reports=state.cases.reduce((n,c)=>n+c.reports.length,0),claims=state.cases.reduce((n,c)=>n+(c.claims?.length||0),0);$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">RAQEEB / VERIFICATION WORKSPACE</div><h1>${T('Verify the claim.<br>Show the evidence.','تحقّق من الادعاء.<br>وأظهر الدليل.')}</h1><p>${T('A transparent newsroom workflow for collecting sources, separating claims from context, testing alternatives, and publishing reviewable assessments.','مسار تحقّق شفاف لجمع المصادر، وفصل الادعاء عن السياق، واختبار البدائل، وإصدار تقدير قابل للمراجعة.')}</p><div class="actions"><button class="btn lime" id="new">${icon('plus')}${T('Start an investigation','ابدأ تحقيقًا')}</button><button class="quiet hero-link" id="sample">${T('Open guided sample ↗','افتح المثال الإرشادي ↗')}</button></div><div class="trust-row"><span>✓ ${T('Human in the loop','قرار بشري')}</span><span>✓ ${T('Source-level evidence','أدلة مرتبطة بالمصدر')}</span><span>✓ ${T('No black-box truth score','دون نسبة حقيقة مبهمة')}</span></div></div><div class="hero-art" aria-hidden="true"><div class="radar-grid"></div><div class="signal signal-a"></div><div class="signal signal-b"></div><div class="evidence-card"><span>CASE REVIEW</span><strong>${T('Traceable','قابل للتتبّع')}</strong><div class="line"></div><div class="line" style="width:72%"></div><span>CLAIM → SOURCE → FINDING</span></div><span class="art-caption">COLLECT · VERIFY · EXPLAIN</span></div></section><div class="workflow"><div><b>01</b><span>${T('Capture the exact claim','ثبّت الادعاء بدقة')}</span></div><div><b>02</b><span>${T('Collect independent origins','اجمع مصادر مستقلة')}</span></div><div><b>03</b><span>${T('Test evidence and alternatives','اختبر الأدلة والبدائل')}</span></div><div><b>04</b><span>${T('Publish a reviewable assessment','أصدر تقديرًا قابلًا للمراجعة')}</span></div></div><div class="stats"><div class="stat"><span>${T('Case files','ملفات القضايا')}</span><strong>${state.cases.length}</strong><small>${T('Auditable workspaces','مساحات قابلة للتدقيق')}</small></div><div class="stat"><span>${T('Claims tracked','الادعاءات المسجّلة')}</span><strong>${claims}</strong><small>${T('With explicit verdicts','بأحكام صريحة')}</small></div><div class="stat"><span>${T('Source materials','مواد المصدر')}</span><strong>${sources}</strong><small>${T('Origins kept separate','مع فصل الأصول')}</small></div><div class="stat"><span>${T('Assessment versions','نسخ التقدير')}</span><strong>${reports}</strong><small>${T('History preserved','مع حفظ السجل')}</small></div></div><div class="row"><div><div class="eyebrow">${T('INVESTIGATION DESK','مكتب التحقيق')}</div><h2>${T('Recent case files','أحدث ملفات القضايا')}</h2></div><a href="#files" class="quiet">${T('View all files →','عرض الملفات ←')}</a></div><div class="grid">${state.cases.length?state.cases.slice(-4).reverse().map(caseCard).join(''):`<div class="card starter-card"><span class="kicker">${T('FAST START','بدء سريع')}</span><h3>${T('Paste a claim or article.','الصق ادعاءً أو مقالًا.')}</h3><p>${T('Create a case, record the exact wording, then attach evidence that supports, contradicts, or contextualizes it.','أنشئ قضية، وسجّل النص الحرفي للادعاء، ثم اربط الأدلة المؤيدة أو المعارضة أو السياقية.')}</p><button class="btn primary" id="new-empty">${T('Create first case','أنشئ أول قضية')}</button></div><div class="card starter-card"><span class="kicker">${T('INTEGRATION READY','جاهز للتكامل')}</span><h3>${T('Connect the services you trust.','اربط الخدمات التي تثق بها.')}</h3><p>${T('A secure server adapter can connect fact-check search, article extraction, archives, media provenance, translation, or any REST API.','يمكن لطبقة خادم آمنة ربط بحث التحقق، واستخراج المقالات، والأرشفة، ومصدر الوسائط، والترجمة، أو أي REST API.')}</p><a class="btn" href="#integrations">${T('View integrations','عرض التكاملات')}</a></div>`}</div><div class="notice"><strong>${T('Editorial principle:','المبدأ التحريري:')}</strong> ${T('Raqeeb organizes evidence and uncertainty; it does not replace the editor and does not label content true or false without a documented basis.','ينظّم رقيب الأدلة وعدم اليقين؛ ولا يستبدل المحرر ولا يصنّف المحتوى صحيحًا أو زائفًا من دون أساس موثّق.')}</div>`;bind('#new','click',newCase);bind('#new-empty','click',newCase);bind('#sample','click',sampleCase);bindCards()}
function renderFiles(){ $('#main').innerHTML=`<div class="row"><div><div class="eyebrow">${T('INVESTIGATION ARCHIVE','أرشيف التحقيقات')}</div><h1>${T('Case files','ملفات القضايا')}</h1></div><button class="btn primary" id="new">${icon('plus')}${T('New case','قضية جديدة')}</button></div><div class="row"><p>${T('A living record of sources, questions and assessments.','سجل متجدد للمصادر والأسئلة والتقديرات.')}</p><input id="search" class="search" aria-label="Search case files" placeholder="${T('Search files…','ابحث في الملفات…')}"></div><div class="grid" id="case-list"></div>`;let list=q=>{$('#case-list').innerHTML=state.cases.filter(c=>(c.title+' '+c.question).toLowerCase().includes(q.toLowerCase())).reverse().map(caseCard).join('')||`<div class="empty">${T('No files found. Create your first case.','لا توجد ملفات مطابقة. أنشئ قضيتك الأولى.')}</div>`;bindCards()};list('');bind('#search','input',e=>list(e.target.value));bind('#new','click',newCase)}
function showModal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function newCase(){showModal(`<div class="row"><h2>${T('Open a case file','إنشاء ملف قضية')}</h2><button class="quiet" data-close aria-label="Close">×</button></div><form id="case-form"><label for="case-title">${T('Case title','عنوان القضية')}</label><input id="case-title" required maxlength="180" placeholder="${T('e.g. Viral claim about the port — verification','مثال: ادعاء متداول حول المرفأ — تحقق')}"><label for="case-question">${T('Primary claim or verification question','الادعاء الأساسي أو سؤال التحقق')}</label><textarea id="case-question" maxlength="1500" placeholder="${T('Write exactly what must be verified, including actor, action, place and time.','اكتب بدقة ما يجب التحقق منه، مع الفاعل والفعل والمكان والوقت.')}" required></textarea><label for="case-horizon">${T('Review deadline (optional)','مهلة المراجعة (اختياري)')}</label><input type="date" id="case-horizon"><button class="btn primary" type="submit">${T('Create file','إنشاء الملف')}</button></form>`);bind('#case-form','submit',e=>{e.preventDefault();let title=$('#case-title').value.trim(),question=$('#case-question').value.trim();if(!title||!question)return;let c={id:uid(),title,question,horizon:$('#case-horizon').value,created:new Date().toISOString(),updated:new Date().toISOString(),sample:false,sources:[],claims:[{id:uid(),text:question,verdict:'unassessed',confidence:'low',source_ids:[],rationale:'',next_step:'',created:new Date().toISOString()}],activity:[],reviews:{},reports:[]};state.cases.push(c);persist();$('#modal').close();tab='claims';location.hash='case/'+c.id})}
function renderCase(){let c=current;c.claims=c.claims||[];c.activity=c.activity||[];let checked=c.claims.filter(x=>x.verdict&&x.verdict!=='unassessed').length,independent=new Set(c.sources.map(s=>s.origin||s.publisher||s.url).filter(Boolean)).size;$('#main').innerHTML=`<div class="row case-head"><div><div class="eyebrow">${T('CASE FILE','ملف قضية')} / ${esc(c.id.slice(0,8))}</div><h1>${esc(c.title)}</h1><p>${esc(c.question)}</p></div><div class="actions"><button class="btn" id="export-case">${icon('download')}${T('Export evidence','تصدير الأدلة')}</button><button class="btn primary" id="analyze" ${busy?'disabled':''}>${T('AI-assisted draft','مسودة بمساعدة AI')}</button></div></div><div class="case-health"><span><b>${c.claims.length}</b>${T(' claims',' ادعاءات')}</span><span><b>${c.sources.length}</b>${T(' sources',' مصادر')}</span><span><b>${independent}</b>${T(' origin groups',' مجموعات أصل')}</span><span><b>${checked}/${c.claims.length||0}</b>${T(' reviewed',' مراجعة')}</span>${c.horizon?`<span><b>⏱</b>${esc(c.horizon)}</span>`:''}</div>${c.sample?`<div class="notice warn">${T('FICTIONAL SAMPLE — all countries, events, sources and assessments in this file are invented for demonstration. This is not live intelligence.','مثال خيالي — جميع الدول والأحداث والمصادر والتقديرات في هذا الملف مؤلفة للعرض. ليست معلومات عن الواقع.')}</div>`:''}<div class="tabs">${[['claims','Claim ledger','سجل الادعاءات'],['sources','Evidence','الأدلة'],['review','Structured review','المراجعة المنهجية'],['report','Assessments','التقديرات'],['timeline','Timeline','التسلسل الزمني']].map(([id,en,ar])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${T(en,ar)} ${id==='claims'?`(${c.claims.length})`:id==='sources'?`(${c.sources.length})`:id==='report'?`(${c.reports.length})`:''}</button>`).join('')}</div><section id="case-content"></section>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderCase()});bind('#export-case','click',()=>download(c.title+'.json',JSON.stringify({version:1,cases:[c]},null,2),'application/json'));bind('#analyze','click',analyzeModal);if(tab==='claims')renderClaims();else if(tab==='sources')renderSources();else if(tab==='review')renderReview();else if(tab==='report')renderReports();else renderTimeline()}

const claimVerdicts=['unassessed','supported','mostly_supported','mixed','misleading','unsupported','unverifiable'];
const claimVerdictName=v=>({unassessed:T('Unassessed','غير مقيّم'),supported:T('Supported','مدعوم'),mostly_supported:T('Mostly supported','مدعوم غالبًا'),mixed:T('Mixed / missing context','مختلط / ينقصه سياق'),misleading:T('Misleading framing','مضلل في التأطير'),unsupported:T('Unsupported','غير مدعوم'),unverifiable:T('Unverifiable','متعذّر التحقق')}[v]||v);
function renderClaims(){let c=current;c.claims=c.claims||[];$('#case-content').innerHTML=`<div class="row"><div><h2>${T('Claim ledger','سجل الادعاءات')}</h2><p class="small">${T('Evaluate each atomic claim separately. A verdict must point to evidence and explain uncertainty.','قيّم كل ادعاء ذري على حدة. يجب أن يرتبط الحكم بدليل وأن يشرح عدم اليقين.')}</p></div><button class="btn primary" id="add-claim">${icon('plus')}${T('Add claim','إضافة ادعاء')}</button></div>${c.claims.map((x,i)=>`<article class="card claim-card"><div class="claim-index">${String(i+1).padStart(2,'0')}</div><div class="claim-body"><div class="row"><span class="badge verdict-${esc(x.verdict||'unassessed')}">${esc(claimVerdictName(x.verdict||'unassessed'))}</span><div class="actions"><button class="quiet" data-search-claim="${x.id}">${T('Search prior fact-checks ↗','ابحث في تحقيقات سابقة ↗')}</button><button class="quiet" data-edit-claim="${x.id}">${T('Review','مراجعة')}</button></div></div><h3 dir="auto">${esc(x.text)}</h3>${x.rationale?`<p dir="auto">${esc(x.rationale)}</p>`:''}<div class="source-meta"><span>${T('Confidence','الثقة')}: ${esc(x.confidence||'low')}</span><span>${T('Evidence','الأدلة')}: ${(x.source_ids||[]).length}</span>${x.next_step?`<span>${T('Next check','الخطوة التالية')}: ${esc(x.next_step)}</span>`:''}</div>${(x.source_ids||[]).length?`<div class="evidence-chips">${x.source_ids.map(id=>{let s=c.sources.find(y=>y.id===id);return s?`<span>${esc(s.title)}</span>`:''}).join('')}</div>`:''}</div></article>`).join('')||`<div class="card empty"><h2>${T('No claims recorded','لا توجد ادعاءات مسجّلة')}</h2><p>${T('Break the story into statements that can be independently checked.','قسّم القصة إلى عبارات يمكن التحقق من كل منها مستقلًا.')}</p></div>`}`;bind('#add-claim','click',()=>claimModal());document.querySelectorAll('[data-edit-claim]').forEach(b=>b.onclick=()=>claimModal(c.claims.find(x=>x.id===b.dataset.editClaim)));document.querySelectorAll('[data-search-claim]').forEach(b=>b.onclick=()=>{let x=c.claims.find(y=>y.id===b.dataset.searchClaim),q=encodeURIComponent(x?.text||'');window.open(`https://toolbox.google.com/factcheck/explorer/search/${q}`,'_blank','noopener,noreferrer')})}
function claimModal(x){showModal(`<div class="row"><h2>${T('Review claim','مراجعة الادعاء')}</h2><button class="quiet" data-close>×</button></div><form id="claim-form"><label for="claim-text">${T('Exact, checkable claim','الادعاء الدقيق القابل للتحقق')}</label><textarea id="claim-text" required maxlength="1200" dir="auto">${esc(x?.text||'')}</textarea><div class="field-row"><div><label for="claim-verdict">${T('Editorial verdict','الحكم التحريري')}</label><select id="claim-verdict">${claimVerdicts.map(v=>`<option value="${v}" ${v===(x?.verdict||'unassessed')?'selected':''}>${claimVerdictName(v)}</option>`).join('')}</select></div><div><label for="claim-confidence">${T('Confidence','الثقة')}</label><select id="claim-confidence">${['low','medium','high'].map(v=>`<option value="${v}" ${v===(x?.confidence||'low')?'selected':''}>${v}</option>`).join('')}</select></div></div><fieldset><legend>${T('Linked evidence','الأدلة المرتبطة')}</legend>${current.sources.map(s=>`<label class="check"><input type="checkbox" name="claim-source" value="${s.id}" ${(x?.source_ids||[]).includes(s.id)?'checked':''}>${esc(s.title)}</label>`).join('')||`<p class="small">${T('Add sources first, then return to link them.','أضف المصادر أولًا ثم عد لربطها.')}</p>`}</fieldset><label for="claim-rationale">${T('Reasoning, counterevidence and uncertainty','التعليل والأدلة المعارضة وعدم اليقين')}</label><textarea id="claim-rationale" maxlength="4000" dir="auto">${esc(x?.rationale||'')}</textarea><label for="claim-next">${T('Next verification step','خطوة التحقق التالية')}</label><input id="claim-next" maxlength="500" value="${esc(x?.next_step||'')}"><div class="actions"><button class="btn primary" type="submit">${T('Save review','حفظ المراجعة')}</button>${x?`<button class="btn danger" type="button" id="delete-claim">${T('Delete','حذف')}</button>`:''}</div></form>`);bind('#claim-form','submit',e=>{e.preventDefault();let item={id:x?.id||uid(),text:$('#claim-text').value.trim(),verdict:$('#claim-verdict').value,confidence:$('#claim-confidence').value,source_ids:[...document.querySelectorAll('[name=claim-source]:checked')].map(el=>el.value),rationale:$('#claim-rationale').value.trim(),next_step:$('#claim-next').value.trim(),created:x?.created||new Date().toISOString(),updated:new Date().toISOString()};if(!item.text)return;if(x)Object.assign(x,item);else current.claims.push(item);current.updated=new Date().toISOString();persist();$('#modal').close();renderClaims()});bind('#delete-claim','click',()=>{if(confirm(T('Delete this claim?','حذف هذا الادعاء؟'))){current.claims=current.claims.filter(y=>y.id!==x.id);persist();$('#modal').close();renderClaims()}})}
function sourceQuality(s){let checks=[s.url,s.date,s.origin||s.publisher,s.author,s.text?.length>200];return Math.round(checks.filter(Boolean).length/checks.length*100)}
function renderSources(){let c=current;$('#case-content').innerHTML=`<div class="row"><div><h2>${T('Evidence collection','مجموعة الأدلة')}</h2><p class="small">${T('Preserve who published what, when, and whether several reports share one origin.','احفظ من نشر ماذا ومتى، وهل تشترك تقارير متعددة في أصل واحد.')}</p></div><button class="btn primary" id="add-source">${icon('plus')}${T('Add evidence','إضافة دليل')}</button></div><div class="notice">${T('A source is not automatically true. Reliability belongs to a specific claim and context; this completeness meter only shows how well the record is documented.','وجود مصدر لا يجعل الادعاء صحيحًا تلقائيًا. الموثوقية ترتبط بادعاء وسياق محددين؛ ومؤشر الاكتمال يبيّن فقط جودة توثيق السجل.')}</div>${c.sources.map(s=>`<article class="card source-card"><div class="row"><div><span class="badge">${esc(s.sourceType||s.kind||'article')}</span><h3>${esc(s.title)}</h3></div><div class="quality-ring" style="--q:${sourceQuality(s)}" title="${T('Record completeness','اكتمال التوثيق')}"><b>${sourceQuality(s)}%</b><small>${T('documented','موثّق')}</small></div></div><div class="source-meta"><span>${T('Publisher','الناشر')}: ${esc(s.publisher||T('Unknown','غير معلوم'))}</span><span>${T('Author','الكاتب')}: ${esc(s.author||T('Unknown','غير معلوم'))}</span><span>${T('Published','النشر')}: ${esc(s.date||T('Unknown','غير معلوم'))}</span><span>${T('Origin group','مجموعة الأصل')}: ${esc(s.origin||T('Unclassified','غير مصنفة'))}</span></div><div class="actions source-actions">${s.url?`<a class="btn" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${T('Open original ↗','فتح الأصل ↗')}</a>`:''}${s.archiveUrl?`<a class="btn" href="${esc(safeURL(s.archiveUrl))}" target="_blank" rel="noopener noreferrer">${T('Open archive ↗','فتح الأرشيف ↗')}</a>`:''}<button class="btn" data-edit-source="${s.id}">${T('Edit record','تعديل السجل')}</button></div><details><summary class="small">${T('Read preserved text','قراءة النص المحفوظ')} · ${(s.text||'').length.toLocaleString()} ${T('characters','حرف')}</summary><div class="source-text" dir="auto">${esc(s.text||'')}</div></details>${s.notes?`<p class="q-details" dir="auto"><strong>${T('Verification notes:','ملاحظات التحقق:')}</strong> ${esc(s.notes)}</p>`:''}<div class="card-foot"><span>${T('Captured','حُفظ')}: ${fmt(s.added)}</span><button class="quiet danger" data-delete-source="${s.id}">${T('Remove','إزالة')}</button></div></article>`).join('')||`<div class="card empty">${icon('files')}<h2>${T('Add your first source','أضف مصدرك الأول')}</h2><p>${T('Paste an article or transcript, import a text file, and preserve its URL and publication details.','الصق مقالًا أو تفريغًا، أو استورد ملفًا نصيًا، واحفظ الرابط وتفاصيل النشر.')}</p></div>`}`;bind('#add-source','click',()=>sourceModal());document.querySelectorAll('[data-edit-source]').forEach(b=>b.onclick=()=>sourceModal(c.sources.find(s=>s.id===b.dataset.editSource)));document.querySelectorAll('[data-delete-source]').forEach(b=>b.onclick=()=>{if(confirm(T('Remove this source? Existing reports keep their evidence snapshots.','إزالة المصدر؟ تحتفظ التقارير السابقة بنسخ أدلتها.'))){c.sources=c.sources.filter(s=>s.id!==b.dataset.deleteSource);c.claims?.forEach(x=>x.source_ids=(x.source_ids||[]).filter(id=>id!==b.dataset.deleteSource));persist();renderCase()}})}
function sourceModal(s){showModal(`<div class="row"><h2>${T('Evidence record','سجل الدليل')}</h2><button class="quiet" data-close aria-label="Close">×</button></div><form id="source-form"><label for="source-url">${T('Original URL (optional)','الرابط الأصلي (اختياري)')}</label><div class="actions"><input id="source-url" type="url" value="${esc(s?.url||'')}" placeholder="https://…" style="flex:1"><button type="button" class="btn" id="fetch-source">${T('Secure fetch','جلب آمن')}</button></div><div id="fetch-message" class="small" role="status"></div><label for="source-title">${T('Title','العنوان')}</label><input id="source-title" required maxlength="300" value="${esc(s?.title||'')}"><div class="field-row"><div><label for="source-type">${T('Material type','نوع المادة')}</label><select id="source-type">${['article','official_statement','document','image','video','social_post','interview','dataset'].map(v=>`<option value="${v}" ${v===(s?.sourceType||'article')?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="source-date">${T('Publication date','تاريخ النشر')}</label><input id="source-date" type="date" value="${esc(s?.date||'')}"></div></div><div class="field-row"><div><label for="source-publisher">${T('Publisher / account','الناشر / الحساب')}</label><input id="source-publisher" maxlength="200" value="${esc(s?.publisher||'')}"></div><div><label for="source-author">${T('Author / speaker','الكاتب / المتحدث')}</label><input id="source-author" maxlength="200" value="${esc(s?.author||'')}"></div></div><div class="field-row"><div><label for="source-origin">${T('Shared original / wire group','الأصل المشترك / مجموعة الوكالة')}</label><input id="source-origin" maxlength="200" value="${esc(s?.origin||'')}" placeholder="${T('Same value for syndicated copies','استخدم القيمة نفسها للنسخ المنقولة')}"></div><div><label for="source-archive">${T('Archive or preserved copy URL','رابط نسخة مؤرشفة')}</label><input id="source-archive" type="url" value="${esc(s?.archiveUrl||'')}" placeholder="https://…"></div></div><label for="source-text">${T('Preserved text or transcript — review before saving','النص أو التفريغ المحفوظ — راجعه قبل الحفظ')}</label><textarea id="source-text" required maxlength="100000" rows="8" dir="auto">${esc(s?.text||'')}</textarea><label for="source-notes">${T('Verification notes, caveats, transformations','ملاحظات التحقق والمحاذير والتعديلات')}</label><textarea id="source-notes" maxlength="3000" rows="3" dir="auto">${esc(s?.notes||'')}</textarea><label for="text-import">${T('Or import a UTF-8 .txt / .md file','أو استورد ملف txt / md بترميز UTF-8')}</label><input id="text-import" type="file" accept=".txt,.md,text/plain"><div class="actions"><button type="submit" class="btn primary">${T('Save evidence','حفظ الدليل')}</button><button type="button" class="btn" data-close>${T('Cancel','إلغاء')}</button></div></form>`);let kind=s?.kind||'pasted';bind('#text-import','change',async e=>{let f=e.target.files[0];if(f){if(f.size>400000)return notify(T('Text file is too large. Limit: 400 KB.','الملف كبير جدًا. الحد 400 كيلوبايت.'));$('#source-text').value=(await f.text()).slice(0,100000);if(!$('#source-title').value)$('#source-title').value=f.name;kind='file'}});bind('#fetch-source','click',async()=>{let b=$('#fetch-source');b.disabled=true;$('#fetch-message').textContent=T('Fetching through the configured server adapter…','جارٍ الجلب عبر موصل الخادم الآمن…');try{let r=await api('fetch',{url:$('#source-url').value});$('#source-title').value=r.title;$('#source-text').value=r.text;$('#source-url').value=r.url;$('#source-publisher').value=r.publisher||'';kind='fetched';$('#fetch-message').textContent=T('Review the extracted text and metadata before saving.','راجع النص والبيانات المستخرجة قبل الحفظ.')}catch(e){$('#fetch-message').textContent=T('No secure fetch adapter is connected. Paste the text now or configure one in Integrations.','لا يوجد موصل جلب آمن متصل. الصق النص الآن أو أضف الموصل من صفحة التكاملات.')}finally{b.disabled=false}});bind('#source-form','submit',e=>{e.preventDefault();let text=$('#source-text').value.trim(),title=$('#source-title').value.trim();if(!text||!title)return;let item={id:s?.id||uid(),title,text,url:$('#source-url').value,date:$('#source-date').value,origin:$('#source-origin').value.trim(),publisher:$('#source-publisher').value.trim(),author:$('#source-author').value.trim(),archiveUrl:$('#source-archive').value,sourceType:$('#source-type').value,notes:$('#source-notes').value.trim(),kind,added:s?.added||new Date().toISOString(),updated:new Date().toISOString()};if(s)Object.assign(s,item);else current.sources.push(item);current.updated=new Date().toISOString();persist();$('#modal').close();renderCase()})}
function renderReview(){let c=current,done=Object.values(c.reviews).filter(r=>!['unassessed','insufficient','not_applicable'].includes(r.status)).length;$('#case-content').innerHTML=`<div class="row"><div><h2>${T('Structured analytical review','مراجعة تحليلية منظمة')}</h2><p class="small">${done}/45 ${T('questions substantively assessed — not a deception score','سؤالًا له تقييم موضوعي — ليست نسبة تضليل')}</p></div><button class="btn" id="manual-report">${T('Save manual assessment','حفظ تقدير يدوي')}</button></div><div class="progress" style="margin-bottom:20px"><i style="width:${done/45*100}%"></i></div><div class="notice">${T('Questions are prompts, not proof. An unknown source is not necessarily false; timing is not causation. The final axis requires team evidence.','الأسئلة أدوات فحص وليست إثباتًا. المصدر المجهول ليس كاذبًا بالضرورة، والتزامن لا يثبت السببية. المحور الأخير يحتاج أدلة من الفريق.')}</div>${AXES.map((a,i)=>`<details class="axis" ${i===2?'open':''}><summary><span class="axis-number">0${i+1}</span><div class="axis-title"><strong>${esc(T(a.en,a.ar))}</strong><small>${T(...scopes[a.scope])}</small></div><span class="badge">${a.questions.filter((q,j)=>c.reviews[`${i+1}.${j+1}`]?.status&&c.reviews[`${i+1}.${j+1}`].status!=='unassessed').length}/5</span></summary>${a.questions.map((q,j)=>questionHTML(`${i+1}.${j+1}`,q,c.reviews[`${i+1}.${j+1}`])).join('')}</details>`).join('')}`;document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewModal(b.dataset.review));bind('#manual-report','click',manualReport)}
function questionHTML(id,q,r){r=r||{status:'unassessed'};return `<div class="question"><h3>${id} · ${esc(T(...q))}</h3><div class="question-meta"><span class="badge ${r.status==='supported'?'amber':''}">${esc(statusName(r.status))}</span>${r.confidence?`<span class="small muted">${T('Confidence','الثقة')}: ${esc(r.confidence)}</span>`:''}<button class="quiet" data-review="${id}">${T('Review / edit','مراجعة / تعديل')}</button></div>${r.quote?`<div class="quote" dir="auto">${esc(r.quote)}</div>`:''}${r.observation?`<p class="q-details" dir="auto">${esc(r.observation)}</p>`:''}${r.alternative?`<p class="q-details">${T('Alternative:','تفسير بديل:')} ${esc(r.alternative)}</p>`:''}${r.next_step?`<p class="q-details">${T('Next check:','الفحص التالي:')} ${esc(r.next_step)}</p>`:''}${r.quote_match===false?`<span class="badge amber">${T('Quotation not found in saved source — verify','الاقتباس غير موجود في المصدر المحفوظ — تحقق منه')}</span>`:''}${r.source_id?`<div class="small muted">${T('Evidence source','مصدر الدليل')}: ${esc(current.sources.find(s=>s.id===r.source_id)?.title||T('Source removed; see report snapshot','أزيل المصدر؛ راجع نسخة التقرير'))}</div>`:''}</div>`}
function reviewModal(id){let [i,j]=id.split('.').map(Number),q=AXES[i-1].questions[j-1],r=current.reviews[id]||{};showModal(`<div class="row"><h2>${T('Review question','مراجعة سؤال')} ${id}</h2><button class="quiet" data-close>×</button></div><p>${esc(T(...q))}</p><form id="review-form"><div class="field-row"><div><label for="r-status">${T('Finding','النتيجة')}</label><select id="r-status">${statuses.map(s=>`<option value="${s}" ${s===(r.status||'unassessed')?'selected':''}>${statusName(s)}</option>`).join('')}</select></div><div><label for="r-confidence">${T('Confidence in assessment','الثقة في التقييم')}</label><select id="r-confidence">${['low','medium','high'].map(s=>`<option ${s===(r.confidence||'low')?'selected':''}>${s}</option>`).join('')}</select></div></div><label for="r-source">${T('Evidence source','مصدر الدليل')}</label><select id="r-source"><option value="">${T('Not selected / team evidence in notes','غير محدد / أدلة الفريق في الملاحظات')}</option>${current.sources.map(s=>`<option value="${s.id}" ${s.id===r.source_id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><label for="r-quote">${T('Exact quotation','اقتباس حرفي')}</label><textarea id="r-quote" rows="2">${esc(r.quote||'')}</textarea><label for="r-observation">${T('Reasoning and evidence / uncertainty','التفسير والأدلة / عدم اليقين')}</label><textarea id="r-observation" required>${esc(r.observation||'')}</textarea><label for="r-alternative">${T('Alternative explanation','تفسير بديل')}</label><textarea id="r-alternative" rows="2">${esc(r.alternative||'')}</textarea><label for="r-next">${T('Next verification step','خطوة التحقق التالية')}</label><input id="r-next" value="${esc(r.next_step||'')}"><button class="btn primary">${T('Save review','حفظ المراجعة')}</button></form>`);bind('#review-form','submit',e=>{e.preventDefault();let status=$('#r-status').value,source_id=$('#r-source').value,quote=$('#r-quote').value.trim();if(['supported','mixed'].includes(status)&&!source_id&&!$('#r-observation').value.trim())return;current.reviews[id]={id,status,source_id,quote,observation:$('#r-observation').value.trim(),alternative:$('#r-alternative').value.trim(),next_step:$('#r-next').value.trim(),confidence:$('#r-confidence').value,quote_match:quote?(current.sources.find(s=>s.id===source_id)?.text||'').includes(quote):null,author:'human',updated:new Date().toISOString()};persist();$('#modal').close();renderReview()})}
function manualReport(){showModal(`<div class="row"><h2>${T('Save an assessment','حفظ تقدير')}</h2><button class="quiet" data-close>×</button></div><form id="manual-form"><label for="summary">${T('Executive assessment','التقدير التنفيذي')}</label><textarea id="summary" required rows="5"></textarea><label for="limitations">${T('Information gaps and limitations','الفجوات والحدود')}</label><textarea id="limitations" required></textarea><label for="reviewer">${T('Analyst / reviewer','المحلل / المراجع')}</label><input id="reviewer" required maxlength="100"><button class="btn primary">${T('Save version','حفظ نسخة')}</button></form>`);bind('#manual-form','submit',e=>{e.preventDefault();current.reports.push({id:uid(),created:new Date().toISOString(),mode:'manual',summary:$('#summary').value,limitations:[$('#limitations').value],reviewer:$('#reviewer').value,claims:[],scenarios:[],changes:'',reviews:structuredClone(current.reviews),sources:structuredClone(current.sources),methodology:'0.1',language:state.settings.lang});persist();$('#modal').close();tab='report';renderCase()})}
function renderReports(){let c=current;$('#case-content').innerHTML=c.reports.length?c.reports.slice().reverse().map((r,idx)=>`<article class="card report-content"><div class="row"><div><span class="badge ${r.mode==='sample'?'amber':''}">${esc(r.mode==='sample'?T('FICTIONAL SAMPLE','مثال خيالي'):r.mode==='ai'?T('AI DRAFT · HUMAN REVIEW REQUIRED','مسودة AI · تتطلب مراجعة بشرية'):T('HUMAN ASSESSMENT','تقدير بشري'))}</span><p class="small" style="margin:8px 0 0">${fmt(r.created)} · ${r.model?esc(r.model):esc(r.reviewer||'')} · v${c.reports.length-idx}</p></div><div class="actions"><button class="btn" data-print="${r.id}">${T('Print / PDF','طباعة / PDF')}</button><button class="btn" data-html="${r.id}">${T('Export report','تصدير التقرير')}</button></div></div><div class="report-summary" dir="auto">${esc(r.summary)}</div>${r.changes?`<div class="notice" dir="auto">${T('Change since previous assessment:','التغير عن التقدير السابق:')} ${esc(r.changes)}</div>`:''}${r.claims?.length?`<h3>${T('Claim ledger','سجل الادعاءات')}</h3><div class="table-wrap"><table><thead><tr><th>${T('Claim','الادعاء')}</th><th>${T('Assessment','التقييم')}</th><th>${T('Evidence','الدليل')}</th></tr></thead><tbody>${r.claims.map(x=>`<tr><td dir="auto">${esc(x.claim)}</td><td dir="auto">${esc(x.verdict)}</td><td dir="auto">${esc(x.reason)}<br><span class="small muted">${esc((x.source_ids||[]).map(id=>r.sources.find(s=>s.id===id)?.title||id).join(' · '))}</span></td></tr>`).join('')}</tbody></table></div>`:''}${r.scenarios?.length?`<h3 style="margin-top:26px">${T('Competing scenarios','السيناريوهات البديلة')}</h3>${r.scenarios.map(s=>`<div class="scenario" dir="auto"><h3>${esc(s.name)}</h3><p class="small">${esc(s.assessment)}</p><p class="small"><strong>${T('Supporting evidence:','أدلة مؤيدة:')}</strong> ${esc(s.support)}</p><p class="small"><strong>${T('Counterevidence:','أدلة معارضة:')}</strong> ${esc(s.against)}</p><p class="small"><strong>${T('What would change this:','ما قد يغيّر التقدير:')}</strong> ${esc(s.trigger)}</p></div>`).join('')}`:''}<h3>${T('Gaps & next checks','الفجوات والفحوص التالية')}</h3><ul class="small muted" dir="auto">${(r.limitations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.research?`<details><summary>${T('Web research notes & cited pages','ملاحظات البحث وصفحاته المستشهد بها')}</summary><p class="small">${T('Search citations are research leads, not independently verified full-text evidence.','استشهادات البحث خيوط للتحقق؛ لم يتحقق التطبيق بشكل مستقل من كامل صفحاتها.')}</p><div class="source-text" dir="auto">${esc(r.research.text)}</div><ul class="link-list">${r.research.citations.map(x=>`<li>${link(x.url,x.title)}</li>`).join('')}</ul></details>`:''}<p class="small muted">${T('Snapshot:','نسخة محفوظة:')} ${r.sources.length} ${T('source(s)','مصادر')} · ${T('Methodology','المنهجية')} ${esc(r.methodology)} ${r.usage?`· ${T('API tokens:','رموز API:')} ${Number(r.usage.input_tokens||0)+Number(r.usage.output_tokens||0)}`:''}</p></article>`).join(''):`<div class="card empty"><h2>${T('No assessment yet','لا يوجد تقدير بعد')}</h2><p>${T('Complete a manual review or connect your AI account to generate a draft.','أكمل مراجعة يدوية أو اربط حساب AI لإنشاء مسودة.')}</p><button class="btn" id="manual-report">${T('Write manual assessment','كتابة تقدير يدوي')}</button></div>`;bind('#manual-report','click',manualReport);document.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>exportReport(c.reports.find(r=>r.id===b.dataset.print),true));document.querySelectorAll('[data-html]').forEach(b=>b.onclick=()=>exportReport(c.reports.find(r=>r.id===b.dataset.html),false))}
function exportReport(r,print){let lang=state.settings.lang;let body=`<p>${esc(state.settings.org)} · رقيب · ${fmt(r.created)}</p><h1>${esc(current.title)}</h1><p>${esc(current.question)}</p><p><strong>${r.mode==='sample'?T('FICTIONAL DEMONSTRATION — NOT REAL EVENTS','مثال خيالي — ليس أحداثًا حقيقية'):r.mode==='ai'?T('AI DRAFT — HUMAN REVIEW REQUIRED','مسودة AI — تتطلب مراجعة بشرية'):T('MANUAL ASSESSMENT','تقدير يدوي')}</strong></p><h2>${T('Assessment','التقدير')}</h2><p>${esc(r.summary)}</p>${r.changes?`<p>${esc(r.changes)}</p>`:''}<h2>${T('Claims','الادعاءات')}</h2>${(r.claims||[]).map(c=>`<p><b>${esc(c.claim)}</b><br>${esc(c.verdict)} — ${esc(c.reason)}<br>${esc((c.source_ids||[]).join(', '))}</p>`).join('')}<h2>${T('Scenarios','السيناريوهات')}</h2>${(r.scenarios||[]).map(s=>`<h3>${esc(s.name)}</h3><p>${esc(s.assessment)}</p><p>${T('For:','مؤيد:')} ${esc(s.support)}</p><p>${T('Against:','معارض:')} ${esc(s.against)}</p><p>${T('Trigger:','مؤشر تغيير:')} ${esc(s.trigger)}</p>`).join('')}<h2>${T('Limitations','الحدود')}</h2><ul>${(r.limitations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>${T('45-question review','مراجعة الأسئلة الـ45')}</h2>${AXES.map((a,i)=>`<h3>${i+1}. ${esc(T(a.en,a.ar))}</h3>${a.questions.map((q,j)=>{let k=`${i+1}.${j+1}`,v=r.reviews[k]||{status:'unassessed'};return `<section><b>${k} ${esc(T(...q))}</b><p>${esc(statusName(v.status))} · ${esc(v.confidence||'')}<br>${esc(v.observation||'')}</p>${v.quote?`<blockquote>${esc(v.quote)}</blockquote>`:''}<p>${T('Source:','المصدر:')} ${esc(v.source_id||'—')}<br>${esc(v.alternative||'')}<br>${esc(v.next_step||'')}</p></section>`}).join('')}`).join('')}<h2>${T('Evidence snapshot','نسخة الأدلة')}</h2>${r.sources.map(s=>`<h3>${esc(s.title)}</h3><p>${esc(s.id)} · ${esc(s.date||'Unknown date')} · ${esc(s.origin||'')}<br>${link(s.url)}</p><pre>${esc(s.text)}</pre>`).join('')}${r.research?`<h2>Web research / ملاحظات البحث</h2><pre>${esc(r.research.text)}</pre><ul>${r.research.citations.map(c=>`<li>${link(c.url,c.title)}</li>`).join('')}</ul>`:''}<p>RAQEEB Demo 0.2 · ${T('Analytical aid, not a validated deception test.','مساعد تحليلي، وليس اختبارًا مُثبتًا لكشف التضليل.')}</p>`;let html=`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><title>${esc(current.title)}</title><style>body{font:15px/1.7 Arial,sans-serif;max-width:900px;margin:40px auto;padding:24px;color:#183329}h1{font-size:30px}h2{border-bottom:1px solid #bbb;padding-bottom:8px;margin-top:32px}pre{white-space:pre-wrap;font:13px/1.7 Arial;overflow-wrap:anywhere}section{border-bottom:1px solid #ddd;padding:12px 0;break-inside:avoid}blockquote{border-inline-start:3px solid #789760;padding-inline-start:15px}a{overflow-wrap:anywhere;color:#166c50}@media print{body{margin:0;padding:10px}}</style><body>${body}</body></html>`;if(print){let w=window.open('','_blank');if(!w)return notify(T('Allow pop-ups to print, or use Export report.','اسمح بالنافذة للطباعة أو استخدم تصدير التقرير.'));w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),300)}else download(current.title+'-report.html',html,'text/html')}
function renderTimeline(){let c=current;$('#case-content').innerHTML=`<div class="row"><h2>${T('Publication & assessment timeline','تسلسل النشر والتقديرات')}</h2></div><div class="notice">${T('Publication dates are entered by the analyst. They are not necessarily event dates. Undated sources are listed separately.','تواريخ النشر يُدخلها المحلل، وقد تختلف عن تواريخ وقوع الأحداث. المصادر غير المؤرخة تظهر منفصلة.')}</div><div class="timeline">${c.sources.filter(s=>s.date).map(s=>({time:s.date,title:s.title,kind:T('Source published','نشر مصدر')})).concat(c.reports.map(r=>({time:r.created,title:r.summary.slice(0,170),kind:T('Assessment saved','حفظ تقدير')}))).sort((a,b)=>a.time.localeCompare(b.time)).map(x=>`<div><span class="badge">${esc(x.time.slice(0,10))}</span><h3>${esc(x.kind)}</h3><p>${esc(x.title)}</p></div>`).join('')||`<p>${T('Add dated sources to build your timeline.','أضف مصادر مؤرخة لبناء التسلسل الزمني.')}</p>`}</div><h3>${T('Undated sources','مصادر غير مؤرخة')}</h3>${c.sources.filter(s=>!s.date).map(s=>`<p>${esc(s.title)}</p>`).join('')||'—'}`}
function renderIntegrations(){let services=[['Fact-check search','بحث التحقق','Google Fact Check Tools / ClaimReview',T('Find previously published fact-checks by claim text or image.','العثور على تحقيقات منشورة سابقًا بواسطة نص الادعاء أو الصورة.'),'factcheck'],['Article extraction','استخراج المقالات','Reader / extraction API',T('Fetch public pages, canonical URL, title, author and publication time.','جلب الصفحات العامة والرابط القياسي والعنوان والكاتب ووقت النشر.'),'extract'],['Web archive','أرشفة الويب','Internet Archive compatible API',T('Preserve a time-stamped copy and detect later changes.','حفظ نسخة مؤرخة ورصد التغييرات اللاحقة.'),'archive'],['Media provenance','مصدر الوسائط','C2PA / Content Credentials',T('Validate signed provenance and edit history when credentials exist.','التحقق من المصدر الموقّع وسجل التعديل عند توفر بيانات الاعتماد.'),'provenance'],['Image & video checks','فحص الصور والفيديو','InVID-style tool adapter',T('Keyframes, metadata, OCR and reverse-search launchers.','الإطارات المفتاحية والبيانات الوصفية وOCR وروابط البحث العكسي.'),'media'],['AI provider','مزود الذكاء الاصطناعي','OpenAI or compatible endpoint',T('Draft claim extraction and summaries with evidence references.','صياغة مسودات استخراج الادعاءات والتلخيص مع مراجع الأدلة.'),'ai'],['Custom REST API','أي REST API','Generic secure adapter',T('Map any JSON API to a named action without exposing its secret in the browser.','ربط أي واجهة JSON بإجراء واضح دون كشف مفتاحها في المتصفح.'),'custom']];let contract='POST /api/connectors/:id/run\nContent-Type: application/json\n\n{\n  "action": "search | fetch | verify | analyze",\n  "case_id": "local-reference",\n  "input": { "url": "https://…", "claim": "…" }\n}\n\n→ { "ok": true, "data": {}, "provenance": {\n    "provider": "…", "retrieved_at": "ISO-8601"\n  }, "warnings": [] }';$('#main').innerHTML=`<div class="integrations-hero"><div><div class="eyebrow">API & TOOL LAYER</div><h1>${T('Connect tools without locking the workflow.','اربط الأدوات من دون تقييد المنهجية.')}</h1><p>${T('Raqeeb keeps one evidence model while services can be added, replaced, or disabled. Manual verification remains available if an API fails.','يحافظ رقيب على نموذج أدلة موحّد، فيما يمكن إضافة الخدمات أو تبديلها أو تعطيلها. ويبقى التحقق اليدوي متاحًا إذا تعطل أي API.')}</p></div><span class="api-shield">{ API }<small>${T('server-side keys','مفاتيح بالخادم')}</small></span></div><div class="notice warn"><strong>${T('Security rule:','قاعدة الأمان:')}</strong> ${T('API secrets must be stored as server environment variables. Never place them in front-end code, a case export, or browser storage.','يجب حفظ مفاتيح API كمتغيرات سرية في الخادم. لا تضعها في الواجهة أو ملف القضية أو تخزين المتصفح.')}</div><div class="integration-grid">${services.map(([en,ar,provider,desc,id],i)=>`<article class="integration-card"><div class="integration-top"><span class="integration-icon">${icon(i===6?'plus':'integrations')}</span><span class="status-dot ${bridge&&['extract','ai'].includes(id)?'on':''}">${bridge&&['extract','ai'].includes(id)?T('Connected','متصل'):T('Ready to connect','جاهز للربط')}</span></div><h3>${T(en,ar)}</h3><small>${esc(provider)}</small><p>${desc}</p><code>/api/connectors/${id}</code></article>`).join('')}</div><section class="card api-contract"><div class="row"><div><span class="kicker">${T('UNIFIED CONTRACT','عقد موحّد')}</span><h2>${T('Add any API through one secure pattern','أضف أي API عبر نمط آمن واحد')}</h2></div><button class="btn" id="copy-contract">${T('Copy example','نسخ المثال')}</button></div><pre id="contract-code" dir="ltr">${esc(contract)}</pre><p class="small">${T('Every result should preserve provider, retrieval time, input hash, warnings, and the raw-response reference. That makes later auditing possible.','يجب أن تحفظ كل نتيجة اسم المزود ووقت الجلب وبصمة المدخل والتحذيرات ومرجع الاستجابة الخام، لتمكين التدقيق لاحقًا.')}</p></section><section class="card"><h2>${T('Designed around proven verification patterns','مبني على أنماط تحقق مجرّبة')}</h2><div class="pattern-list"><div><b>ClaimReview</b><span>${T('Structured claim, publisher, date and human-readable rating.','ادعاء منظم وناشر وتاريخ وتقييم مفهوم.')}</span></div><div><b>InVID / WeVerify</b><span>${T('A toolbox approach for images, video, metadata and reverse search.','نهج صندوق أدوات للصور والفيديو والبيانات والبحث العكسي.')}</span></div><div><b>C2PA</b><span>${T('Cryptographic provenance is reported separately from whether the content is true.','يُعرض المصدر المشفّر منفصلًا عن الحكم على صحة المحتوى.')}</span></div><div><b>Meedan Check</b><span>${T('Collaborative annotation, verification, archiving and translation workflows.','مسارات تعاونية للتعليق والتحقق والأرشفة والترجمة.')}</span></div></div></section>`;bind('#copy-contract','click',async()=>{try{await navigator.clipboard.writeText(contract);notify(T('API contract copied','نُسخ عقد API'))}catch{notify(T('Select and copy the example manually.','حدد المثال وانسخه يدويًا.'))}})}
function renderMethod(){$('#main').innerHTML=`<div class="eyebrow">${T('TRANSPARENT BY DESIGN','منهجية واضحة')}</div><h1>${T('The analytical framework','الإطار التحليلي')}</h1><p>${T('A claim-first workflow plus nine contextual lenses and forty-five review questions.','مسار يبدأ بالادعاء، مع تسعة محاور سياقية وخمسة وأربعين سؤال مراجعة.')}</p><div class="notice warn">${T('This is a review framework, not a lie detector. A verdict describes the available evidence at a stated time; it can change when better evidence appears.','هذا إطار مراجعة وليس كاشف كذب. يصف الحكم الأدلة المتاحة في وقت محدد، وقد يتغير عند ظهور أدلة أفضل.')}</div><div class="method-steps"><div><b>1</b><span>${T('Write one atomic, checkable claim.','اكتب ادعاءً ذريًا قابلًا للتحقق.')}</span></div><div><b>2</b><span>${T('Identify the earliest available origin.','حدّد أقدم أصل متاح.')}</span></div><div><b>3</b><span>${T('Seek independent support and counterevidence.','ابحث عن دعم مستقل وأدلة معارضة.')}</span></div><div><b>4</b><span>${T('State verdict, confidence, gaps and next step.','اذكر الحكم والثقة والفجوات والخطوة التالية.')}</span></div></div>${AXES.map((a,i)=>`<details class="axis"><summary><span class="axis-number">0${i+1}</span><div class="axis-title"><strong>${T(a.en,a.ar)}</strong><small>${T(...scopes[a.scope])}</small></div></summary><div class="question"><ol>${a.questions.map(q=>`<li>${esc(T(...q))}</li>`).join('')}</ol></div></details>`).join('')}<div class="card"><h2>${T('Interpretation rules','قواعد التفسير')}</h2><ul><li>${T('Insufficient information is a valid result. Missing evidence is not proof of absence.','نقص المعلومات نتيجة صحيحة. غياب الدليل لا يثبت غياب الحدث.')}</li><li>${T('Repetition is not independent corroboration; use origin groups.','التكرار ليس تأكيدًا مستقلًا؛ استخدم مجموعات الأصل.')}</li><li>${T('Separate factual accuracy, framing, coordination and intent.','افصل صحة الوقائع عن التأطير والتنسيق والقصد.')}</li><li>${T('C2PA provenance can show origin and edits, but does not by itself prove that content is factually true.','قد يثبت C2PA المصدر والتعديلات، لكنه لا يثبت وحده صحة المحتوى واقعيًا.')}</li><li>${T('AI output is always a draft requiring source-level human review.','مخرجات AI مسودة دائمًا وتتطلب مراجعة بشرية على مستوى المصدر.')}</li></ul><h3>${T('Reference tools and standards — no affiliation or certification','أدوات ومعايير مرجعية — دون ادعاء انتساب أو اعتماد')}</h3><p class="method-ref">${link('https://developers.google.com/search/docs/appearance/structured-data/factcheck','ClaimReview')} · ${link('https://toolbox.google.com/factcheck/apis','Fact Check Tools API')} · ${link('https://weverify.eu/verification-plugin/','InVID / WeVerify')} · ${link('https://c2pa.org/specifications/specifications/2.2/explainer/Explainer.html','C2PA')} · ${link('https://meedan.org/our-tools','Meedan Check')} · ${link('https://www.disarm.foundation/framework','DISARM')}</p></div>`}
function renderSettings(){$('#main').innerHTML=`<div class="eyebrow">${T('INDEPENDENT BY DESIGN','استقلالية في التشغيل')}</div><h1>${T('Your workspace, your control.','مساحتك، تحت سيطرتك.')}</h1><div class="grid"><section class="card"><h2>${T('AI connection','اتصال الذكاء الاصطناعي')}</h2><p class="small">${T('Your own OpenAI API account. The key is held only in the local launcher’s memory and is never included in backups. Reconnect after restarting the launcher.','حساب OpenAI API خاص بك. يُحفظ المفتاح في ذاكرة المشغّل فقط ولا يدخل النسخ الاحتياطية. أعد الربط بعد إعادة تشغيل المشغّل.')}</p>${!bridge?`<div class="notice warn">${T('This shared browser demo saves data on this device. AI analysis and automatic URL extraction are available in the full desktop version.','هذه نسخة تجريبية مشتركة تحفظ البيانات على هذا الجهاز. تحليل AI وجلب المقال تلقائيًا من الرابط متاحان في نسخة الكمبيوتر الكاملة.')}</div>`:''}<label for="api-key">OpenAI API key</label><input type="password" id="api-key" autocomplete="off" placeholder="sk-…"><label for="model">${T('Model ID available in your API account','معرّف نموذج متاح في حساب API')}</label><input id="model" value="${esc(state.settings.model)}" maxlength="100"><p class="small">${T('Model access and tool availability depend on your account. You can change the model ID.','توفر النموذج وأدواته يعتمد على حسابك. يمكنك تغيير المعرّف.')}</p><div class="actions"><button class="btn primary" id="connect">${T('Connect & check key','ربط وفحص المفتاح')}</button><button class="btn" id="disconnect">${T('Forget key','نسيان المفتاح')}</button></div><p id="connection-result" class="small" role="status"></p><p class="small">${T('Analysis sends your selected source texts to OpenAI. Optional web research can send topic information to search services. API and search charges are paid by the account owner.','يرسل التحليل نصوص المصادر إلى OpenAI. البحث الاختياري قد يرسل معلومات الموضوع إلى خدمات البحث. تكاليف API والبحث على صاحب الحساب.')}</p></section><section class="card"><h2>${T('Workspace & backup','مساحة العمل والنسخ الاحتياطي')}</h2><label for="org">${T('Institution / report heading','المؤسسة / ترويسة التقرير')}</label><input id="org" value="${esc(state.settings.org)}" maxlength="200"><label for="output-lang">${T('Default report language','لغة التقرير الافتراضية')}</label><input id="output-lang" value="${esc(state.settings.reportLanguage)}" list="languages" maxlength="80"><datalist id="languages"><option>Arabic</option><option>English</option><option>French</option><option>Persian</option><option>Turkish</option><option>Azerbaijani</option></datalist><button class="btn" id="save-settings">${T('Save preferences','حفظ التفضيلات')}</button><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><p class="small">${bridge?T('Case files are saved in the local SQLite database and mirrored in this browser. Back up regularly.','تُحفظ الملفات في قاعدة SQLite المحلية ونسخة في المتصفح. أنشئ نسخًا احتياطية دوريًا.'):T('Preview files are saved in this browser only. Clearing browser data can erase them; export a backup before changing browser or launch mode.','ملفات العرض محفوظة في هذا المتصفح فقط. قد تُحذف عند مسح بياناته؛ صدّر نسخة قبل تغيير المتصفح أو وضع التشغيل.')}</p><div class="actions"><button class="btn" id="backup">${icon('download')}${T('Export all data','تصدير جميع البيانات')}</button><button class="btn" id="restore">${T('Import backup','استيراد نسخة')}</button></div><p class="small">${T('Backups contain source texts and reports; they are not encrypted. This demo is for a single local user, with no activation or remote control.','النسخ تتضمن النصوص والتقارير وغير مشفرة. النسخة لمستخدم محلي واحد، دون تفعيل أو تحكم عن بُعد.')}</p></section></div>`;bind('#save-settings','click',()=>{state.settings.org=$('#org').value.trim();state.settings.reportLanguage=$('#output-lang').value.trim()||'Arabic';state.settings.model=$('#model').value.trim();persist();notify(T('Preferences saved','حُفظت التفضيلات'))});bind('#connect','click',async()=>{let b=$('#connect');b.disabled=true;try{let r=await api('connect',{key:$('#api-key').value.trim(),model:$('#model').value.trim()});$('#api-key').value='';state.settings.model=$('#model').value.trim();persist();$('#connection-result').textContent=r.message}catch(e){$('#connection-result').textContent=e.message}finally{b.disabled=false}});bind('#disconnect','click',async()=>{try{await api('disconnect',{});$('#api-key').value='';$('#connection-result').textContent=T('Key removed from memory.','أُزيل المفتاح من الذاكرة.')}catch(e){notify(e.message)}});bind('#backup','click',()=>download('RAQEEB-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json'));bind('#restore','click',()=>$('#backup-input').click())}
function analyzeModal(){if(!current.sources.length)return notify(T('Add at least one source first.','أضف مصدرًا واحدًا على الأقل.'));if(!bridge){notify(T('AI analysis is available in the full desktop version.','تحليل AI متاح في نسخة الكمبيوتر الكاملة.'));return}showModal(`<div class="row"><h2>${T('Generate an evidence-led draft','إنشاء مسودة تستند إلى الأدلة')}</h2><button class="quiet" data-close>×</button></div><p>${T('The selected file’s sources and question will be sent to your AI provider. This uses your API credit. Existing assessments remain saved.','ستُرسل مصادر الملف وسؤاله إلى مزود AI باستخدام رصيدك. تبقى التقديرات السابقة محفوظة.')}</p><label for="analysis-lang">${T('Report language','لغة التقرير')}</label><input id="analysis-lang" value="${esc(state.settings.reportLanguage)}" maxlength="80"><label class="check"><input type="checkbox" id="research">${T('Allow web research for public topics (additional cost; not for confidential case details).','السماح بالبحث عن الموضوع العام (تكلفة إضافية؛ لا تستخدمه مع تفاصيل سرية).')}</label><label class="check"><input type="checkbox" id="consent">${T('I am authorized to send these source texts to the AI provider.','لدي صلاحية إرسال هذه النصوص إلى مزود الذكاء الاصطناعي.')}</label><div class="notice">${T('Drafts may be wrong. Quotes are checked against saved text; sources and conclusions still need editorial review. Up to 60,000 source characters per run.','المسودات قد تخطئ. تُطابق الاقتباسات مع النصوص المحفوظة وتبقى مراجعة المصادر والاستنتاجات ضرورية. الحد 60,000 حرف للمصادر في كل عملية.')}</div><button class="btn primary" id="run-ai">${T('Run analysis','بدء التحليل')}</button><div id="ai-status" role="status"></div>`);bind('#run-ai','click',async()=>{if(!$('#consent').checked)return notify(T('Please confirm permission to process these texts.','يرجى تأكيد صلاحية معالجة النصوص.'));let c=current,language=$('#analysis-lang').value.trim()||'Arabic',research=$('#research').checked;busy=true;$('#run-ai').disabled=true;$('#ai-status').innerHTML=`<div class="busy"><span class="spinner"></span><p>${T('Reviewing sources and hypotheses… This can take a few minutes. Keep this window open.','جارٍ مراجعة المصادر والفرضيات… قد تستغرق دقائق. أبقِ النافذة مفتوحة.')}</p></div>`;try{let out=await api('analyze',{case:c,language,research});c.reports.push(out);c.reviews=out.reviews;persist();$('#modal').close();tab='report';renderCase();notify(T('Draft saved. Review evidence before relying on it.','حُفظت المسودة. راجع الأدلة قبل الاعتماد عليها.'))}catch(e){$('#ai-status').textContent=e.message;$('#run-ai').disabled=false}finally{busy=false;const button=$('#analyze');if(button)button.disabled=false}})}
function download(name,content,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name.replace(/[<>:"/\\|?*]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function sampleCase(){let existing=state.cases.find(c=>c.sample);if(existing){tab='report';location.hash='case/'+existing.id;return}let c={id:uid(),title:T('Aster–Boreal: escalation or pressure?','أستر وبوريال: تصعيد أم ضغط؟'),question:T('Fictional exercise: what do three supplied reports support about escalation in the next 30 days?','تمرين خيالي: ماذا تدعم ثلاثة تقارير عن التصعيد خلال 30 يومًا؟'),horizon:'',created:new Date().toISOString(),sample:true,sources:[],reviews:{},reports:[]};let texts=[['Anonymous briefing / إحاطة مجهولة','2030-01-05','Wire A','FICTIONAL TRAINING MATERIAL. Aster officials warned of serious consequences. An unnamed source said a decision was imminent. No documents or independently verified deployments were provided. This statement does not establish that an attack has been authorized.'],['Repeated dispatch / إعادة نشر','2030-01-06','Wire A','FICTIONAL TRAINING MATERIAL. An unnamed source said a decision was imminent. This report reproduces the same Wire A dispatch without additional reporting.'],['Mediation update / تحديث الوساطة','2030-01-07','Mediator bulletin','FICTIONAL TRAINING MATERIAL. The mediator announced that delegations from Aster and Boreal would meet on January 10. Neither government had confirmed attendance in the material supplied. No independent military observation is included.']];c.sources=texts.map(([title,date,origin,text])=>({id:uid(),title,date,origin,text,url:'',kind:'fictional',added:new Date().toISOString()}));let ids=c.sources.map(s=>s.id);AXES.forEach((a,i)=>a.questions.forEach((q,j)=>{c.reviews[`${i+1}.${j+1}`]={id:`${i+1}.${j+1}`,status:'insufficient',confidence:'low',source_id:'',quote:'',observation:T('The supplied fictional material does not establish this finding.','المادة الخيالية المتاحة لا تكفي لإثبات هذا المؤشر.'),alternative:'',next_step:T(a.scope==='team'?'Ask the analysis team to document how alternatives were considered.':'Obtain independent evidence and an appropriate comparison baseline.',a.scope==='team'?'اطلب من فريق التحليل توثيق كيفية فحص البدائل.':'اجمع أدلة مستقلة وخط أساس مناسب للمقارنة.'),author:'sample'}}));for(let id of ['2.2','2.4'])Object.assign(c.reviews[id],{status:'supported',confidence:'high',source_id:ids[1],quote:'This report reproduces the same Wire A dispatch without additional reporting.',quote_match:true,observation:T('The second item explicitly republishes the first dispatch; it is not an independent confirmation.','المادة الثانية تعيد نقل البرقية نفسها صراحة؛ ليست تأكيدًا مستقلًا.'),alternative:T('Ordinary syndication can explain this repetition; intent to flood is not established.','قد يفسر النقل الصحافي الطبيعي هذا التكرار؛ لم يثبت قصد الإغراق.')});Object.assign(c.reviews['3.1'],{status:'supported',confidence:'high',source_id:ids[0],quote:'An unnamed source said a decision was imminent.',quote_match:true,observation:T('The key statement is attributed to an unnamed source.','التصريح الأساسي منسوب إلى مصدر غير مسمى.'),alternative:T('Anonymity can protect legitimate sources.','قد يحمي حجب الهوية مصادر مشروعة.')});let r={id:uid(),created:new Date().toISOString(),mode:'sample',methodology:'0.1',language:state.settings.lang,summary:T('The supplied fictional reports establish threatening rhetoric and repeated reporting, but do not establish an authorized attack. Continued pressure and limited escalation remain competing possibilities. The evidence is insufficient to rank them reliably.','تثبت التقارير الخيالية وجود خطاب تهديد وتكرار للنقل، لكنها لا تثبت اتخاذ قرار بالهجوم. يبقى استمرار الضغط والتصعيد المحدود احتمالين بديلين. لا تكفي الأدلة لترتيبهما بثقة.'),claims:[{claim:T('An attack decision is imminent.','قرار الهجوم وشيك.'),verdict:T('Unverified','غير متحقق'),reason:T('Single anonymous origin; no independent corroboration.','أصل مجهول واحد دون تأكيد مستقل.'),source_ids:[ids[0],ids[1]]},{claim:T('Mediation talks are planned.','محادثات وساطة مرتقبة.'),verdict:T('Attributed announcement','إعلان منسوب إلى جهة'),reason:T('Announced by the fictional mediator; attendance not confirmed.','أعلنها الوسيط الخيالي دون تأكيد الحضور.'),source_ids:[ids[2]]}],scenarios:[{name:T('Continued pressure','استمرار الضغط'),assessment:T('Plausible; not assigned a probability.','محتمل؛ دون نسبة احتمالية.'),support:T('Threatening statements alongside announced mediation.','تصريحات تهديد مع إعلان وساطة.'),against:T('Attendance is unconfirmed and military context is missing.','الحضور غير مؤكد والسياق العسكري ناقص.'),trigger:T('Independently confirmed talks and concrete de-escalatory actions.','تأكيد مستقل للمحادثات وخطوات تهدئة ملموسة.')},{name:T('Limited escalation','تصعيد محدود'),assessment:T('Cannot be excluded; insufficient evidence to prefer it.','لا يمكن استبعاده؛ الأدلة غير كافية لترجيحه.'),support:T('Threatening rhetoric is present, but is weak evidence of action.','يوجد خطاب تهديد لكنه دليل ضعيف على الفعل.'),against:T('No verified preparations or authorizing decision supplied.','لا توجد أدلة مقدمة على استعدادات أو قرار موثق.'),trigger:T('Independent, dated evidence of relevant actions.','أدلة مستقلة ومؤرخة على تحركات ذات صلة.')}],limitations:[T('All materials are fictional. Do not apply these findings to real events.','كل المواد خيالية. لا تطبق هذه النتائج على أحداث حقيقية.'),T('Two reports share one origin. No military baseline or team deliberation records are available.','تقريران من أصل واحد. لا يوجد خط أساس عسكري أو سجل مداولات الفريق.')],reviews:structuredClone(c.reviews),sources:structuredClone(c.sources),changes:''};c.reports.push(r);state.cases.push(c);persist();tab='report';location.hash='case/'+c.id;}
function validateBackup(x){if(x.version!==1||!Array.isArray(x.cases)||x.cases.length>500)throw Error('Invalid backup format');for(let c of x.cases){if(typeof c.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(c.id)||typeof c.title!=='string'||!Array.isArray(c.sources)||!Array.isArray(c.reports)||!c.reviews||typeof c.reviews!=='object')throw Error('Invalid case file');for(let s of c.sources){if(typeof s.text!=='string'||typeof s.title!=='string'||typeof s.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(s.id))throw Error('Invalid source')}for(let r of c.reports){if(typeof r.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(r.id)||typeof r.summary!=='string'||!Array.isArray(r.sources)||!r.reviews||!Array.isArray(r.limitations)||!Array.isArray(r.claims)||!Array.isArray(r.scenarios))throw Error('Invalid report');}}return x}
bind('#backup-input','change',async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error('Backup exceeds 10 MB');let x=validateBackup(JSON.parse(await f.text()));let fresh=x.cases.filter(c=>!state.cases.some(o=>o.id===c.id));state.cases.push(...fresh);persist();render();notify(T(`Imported ${fresh.length} file(s). Existing IDs were not overwritten.`,`تم استيراد ${fresh.length} ملف. لم تُستبدل الملفات الموجودة.`))}catch(e){notify(T('Could not import: ','تعذر الاستيراد: ')+e.message)}finally{e.target.value=''}});
bind('#lang','click',()=>{state.settings.lang=state.settings.lang==='ar'?'en':'ar';persist();render()});window.addEventListener('hashchange',render);
async function init(){try{let saved=localStorage.getItem('raqeeb-v1');if(saved){let x=validateBackup(JSON.parse(saved));state={...state,...x,settings:{...state.settings,...x.settings}}}}catch{}if(location.protocol.startsWith('http'))try{let r=await fetch('/api/session');if(r.ok){let x=await r.json();token=x.token;bridge=true;let saved=await api('state');if(saved.state){validateBackup(saved.state);state={...state,...saved.state,settings:{...state.settings,...saved.state.settings}}}else persist()}}catch{}render()}
init();
